package dev.langchain4j.agent.tool;
import java.util.*;
import static dev.langchain4j.internal.Utils.quoted;
import static java.util.Arrays.asList;
public class ToolSpecification {
 public static final String METADATA_SEARCH_BEHAVIOR="searchBehavior"; private final String name,description;private final ToolParameters parameters;private final Map<String,Object> metadata;private final Boolean strict;
 private ToolSpecification(Builder b){name=b.name;description=b.description;parameters=b.parameters;metadata=b.metadata==null?Collections.<String,Object>emptyMap():Collections.unmodifiableMap(new LinkedHashMap<String,Object>(b.metadata));strict=b.strict;}
 public String name(){return name;}public String description(){return description;}public ToolParameters parameters(){return parameters;}public Map<String,Object> metadata(){return metadata;}public Boolean strict(){return strict;}
 public Builder toBuilder(){return builder().name(name).description(description).parameters(parameters).metadata(new LinkedHashMap<String,Object>(metadata)).strict(strict);}public static Builder builder(){return new Builder();}
 public boolean equals(Object o){if(this==o)return true;if(!(o instanceof ToolSpecification))return false;ToolSpecification t=(ToolSpecification)o;return Objects.equals(name,t.name)&&Objects.equals(description,t.description)&&Objects.equals(parameters,t.parameters)&&Objects.equals(metadata,t.metadata)&&Objects.equals(strict,t.strict);}public int hashCode(){return Objects.hash(name,description,parameters,metadata,strict);}public String toString(){return "ToolSpecification { name = "+quoted(name)+", description = "+quoted(description)+", parameters = "+parameters+", metadata = "+metadata+", strict = "+strict+" }";}
 public static final class Builder {private String name,description;private ToolParameters parameters;private Map<String,Object> metadata=new HashMap<String,Object>();private Boolean strict;private Builder(){}public Builder name(String v){name=v;return this;}public Builder description(String v){description=v;return this;}public Builder parameters(ToolParameters v){parameters=v;return this;}public Builder metadata(Map<String,Object>v){metadata=v==null?new HashMap<String,Object>():v;return this;}public Builder addMetadata(String k,Object v){metadata.put(k,v);return this;}public Builder strict(Boolean v){strict=v;return this;}public Builder addParameter(String n,JsonSchemaProperty...p){return addParameter(n,asList(p));}public Builder addParameter(String n,Iterable<JsonSchemaProperty>p){addOptionalParameter(n,p);parameters.required().add(n);return this;}public Builder addOptionalParameter(String n,JsonSchemaProperty...p){return addOptionalParameter(n,asList(p));}public Builder addOptionalParameter(String n,Iterable<JsonSchemaProperty>p){if(parameters==null)parameters=ToolParameters.builder().build();Map<String,Object>m=new HashMap<String,Object>();for(JsonSchemaProperty x:p)m.put(x.key(),x.value());parameters.properties().put(n,m);return this;}public ToolSpecification build(){return new ToolSpecification(this);}}
}
